contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 dummy) public {
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        bool wageredBefore = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.play(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        bool wageredAfter = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        assert(wageredBefore == false && reverted && wageredAfter == false);
    }
    receive() external payable {}
}

