// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 dummy) internal {
        try c.OpenToThePublic() {} catch { return; }
        bool wageredBefore;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { wageredBefore = __r; } catch { return; }
        bool reverted;
        try c.play() { reverted = false; } catch { reverted = true; }
        bool wageredAfter;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { wageredAfter = __r; } catch { return; }
        assertTrue(wageredBefore == false && reverted && wageredAfter == false);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
